mapper.update:
UPDATE ai_conversation_generation
SET generation_status = #{runningStatus,jdbcType=SMALLINT},
    owner_instance_id = #{ownerInstanceId,jdbcType=VARCHAR},
    started_at = COALESCE(started_at, #{now,jdbcType=TIMESTAMP_WITH_TIMEZONE}),
    updated_at = #{now,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE id = #{generationId,jdbcType=BINARY}
  AND generation_status = #{queuedStatus,jdbcType=SMALLINT}

UPDATE ai_conversation_generation
SET observer_status = #{attachedStatus,jdbcType=SMALLINT},
    observer_epoch = observer_epoch + 1,
    detached_at = NULL,
    updated_at = #{now,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE id = #{generationId,jdbcType=BINARY}
  AND login_identity_id = #{loginIdentityId,jdbcType=BIGINT}

UPDATE ai_conversation_generation
SET observer_status = #{detachedStatus,jdbcType=SMALLINT},
    detached_at = COALESCE(detached_at, #{now,jdbcType=TIMESTAMP_WITH_TIMEZONE}),
    updated_at = #{now,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE id = #{generationId,jdbcType=BINARY}
  AND login_identity_id = #{loginIdentityId,jdbcType=BIGINT}
  AND observer_epoch = #{expectedEpoch,jdbcType=BIGINT}
  AND observer_status = #{attachedStatus,jdbcType=SMALLINT}

UPDATE ai_conversation_generation
SET generation_status = #{cancelRequestedStatus,jdbcType=SMALLINT},
    cancel_source = #{cancelSource,jdbcType=VARCHAR},
    cancel_requested_at = #{now,jdbcType=TIMESTAMP_WITH_TIMEZONE},
    updated_at = #{now,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE id = #{generationId,jdbcType=BINARY}
  AND generation_status IN

      #{status,jdbcType=SMALLINT}

  AND cancel_source IS NULL

UPDATE ai_conversation_generation
SET generation_status = #{terminalPendingStatus,jdbcType=SMALLINT},
    terminal_type = #{terminalType,jdbcType=VARCHAR},
    terminal_reason = #{terminalReason,jdbcType=VARCHAR},
    terminal_version = terminal_version + 1,
    terminal_at = #{now,jdbcType=TIMESTAMP_WITH_TIMEZONE},
    updated_at = #{now,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE id = #{generationId,jdbcType=BINARY}
  AND terminal_version = #{expectedTerminalVersion,jdbcType=INTEGER}
  AND terminal_type IS NULL
  AND generation_status IN

      #{status,jdbcType=SMALLINT}

UPDATE ai_conversation_generation
SET generation_status = #{finalStatus,jdbcType=SMALLINT},
    settled_at = #{now,jdbcType=TIMESTAMP_WITH_TIMEZONE},
    updated_at = #{now,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE id = #{generationId,jdbcType=BINARY}
  AND generation_status = #{terminalPendingStatus,jdbcType=SMALLINT}
  AND terminal_version = #{expectedTerminalVersion,jdbcType=INTEGER}

UPDATE ai_conversation_generation
SET generation_status = #{reconcileStatus,jdbcType=SMALLINT},
    terminal_reason = COALESCE(terminal_reason, #{terminalReason,jdbcType=VARCHAR}),
